CREATE TYPE "ChatConversationVisibility" AS ENUM ('PRIVATE', 'ORGANIZATION');
CREATE TYPE "PersistedChatMessageRole" AS ENUM ('USER', 'ASSISTANT', 'SYSTEM');
CREATE TYPE "PersistedChatMessageStatus" AS ENUM ('PENDING', 'COMPLETED', 'FAILED');
CREATE TABLE "ChatConversation" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"ownerId" TEXT NOT NULL,"title" TEXT NOT NULL,"agentCode" TEXT NOT NULL,"visibility" "ChatConversationVisibility" NOT NULL DEFAULT 'PRIVATE',"nextSequence" INTEGER NOT NULL DEFAULT 1,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ChatConversation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ChatMessage" ("id" TEXT NOT NULL,"conversationId" TEXT NOT NULL,"authorId" TEXT,"sequence" INTEGER NOT NULL,"role" "PersistedChatMessageRole" NOT NULL,"content" TEXT NOT NULL,"modelContext" TEXT,"attachments" JSONB NOT NULL DEFAULT '[]',"generatedFiles" JSONB NOT NULL DEFAULT '[]',"thinking" TEXT,"status" "PersistedChatMessageStatus" NOT NULL DEFAULT 'COMPLETED',"clientRequestId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ChatMessage_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ChatConversation_organizationId_updatedAt_idx" ON "ChatConversation"("organizationId","updatedAt"); CREATE INDEX "ChatConversation_ownerId_updatedAt_idx" ON "ChatConversation"("ownerId","updatedAt"); CREATE UNIQUE INDEX "ChatMessage_conversationId_sequence_key" ON "ChatMessage"("conversationId","sequence"); CREATE UNIQUE INDEX "ChatMessage_conversationId_clientRequestId_key" ON "ChatMessage"("conversationId","clientRequestId"); CREATE INDEX "ChatMessage_conversationId_createdAt_idx" ON "ChatMessage"("conversationId","createdAt");
ALTER TABLE "ChatConversation" ADD CONSTRAINT "ChatConversation_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ChatConversation" ADD CONSTRAINT "ChatConversation_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ChatMessage" ADD CONSTRAINT "ChatMessage_conversationId_fkey" FOREIGN KEY ("conversationId") REFERENCES "ChatConversation"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ChatMessage" ADD CONSTRAINT "ChatMessage_authorId_fkey" FOREIGN KEY ("authorId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
